<?php
namespace App\Services;use App\Models\Order;use App\Models\PaymentTransaction;use App\Payments\ConfiguredGateway;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class PaymentService{public function initiate(Order $order,string $method):array{return DB::transaction(function()use($order,$method){$order=Order::lockForUpdate()->findOrFail($order->id);if($order->payment_status==='paid')throw ValidationException::withMessages(['payment'=>'Order is already paid.']);$tx=PaymentTransaction::firstOrCreate(['merchant_reference'=>$order->number.'-'.$method],['uuid'=>(string)Str::uuid(),'order_id'=>$order->id,'gateway'=>$method,'status'=>'initiated','amount'=>$order->grand_total,'currency'=>$order->currency]);$order->update(['payment_method'=>$method]);if($method==='cod'){$tx->update(['status'=>'authorized','verified_at'=>now()]);$order->update(['status'=>'confirmed','payment_status'=>'cod_pending']);return ['redirect'=>route('payment.complete',$order->uuid)];}return (new ConfiguredGateway($method))->initiate($order,$tx);});}}
